const resources=[{name:'○○社區關懷據點－長者棋藝活動',short:'長者棋藝活動',tags:['下棋','社交','室內活動'],place:'臺中市西區 ○○里活動中心',day:'週二、週五',time:'14:00–16:00',traffic:'步行約 10 分鐘／公車可達',type:'棋藝',area:'西區',symbol:'♟',desc:'由據點志工協助安排棋友，歡迎先來看看，也可由熟悉的人陪同首次參與。'},{name:'○○社區共餐',short:'社區共餐',tags:['共餐','社交'],place:'臺中市西區 ○○社區食堂',day:'週一、週四',time:'11:30–13:00',traffic:'公車可達',type:'共餐',area:'西區',symbol:'♧',desc:'一起吃頓飯、聊聊生活。參加前需由工作人員確認報名與餐食安排。'},{name:'公園晨間健走團',short:'公園健走團',tags:['戶外','健走'],place:'臺中市南區 ○○公園',day:'週三',time:'08:00–09:00',traffic:'需接送',type:'健走',area:'南區',symbol:'↟',desc:'依個人意願與狀況選擇路線，參與前請確認交通與步行需求。'},{name:'社區生活手作課程',short:'手作課程',tags:['手作','室內活動'],place:'臺中市西區 ○○學習中心',day:'週六',time:'10:00–12:00',traffic:'公車可達',type:'手作',area:'西區',symbol:'✂',desc:'以簡單生活手作為主，材料由據點準備，可先詢問當週主題。'},{name:'一起唱歌・社區歌唱活動',short:'社區歌唱活動',tags:['歌唱','社交'],place:'臺中市北區 ○○活動中心',day:'週三',time:'14:00–16:00',traffic:'需接送',type:'歌唱',area:'北區',symbol:'♫',desc:'透過熟悉的歌曲與同伴交流，歡迎自由選擇聆聽或一起唱。'}];
const brand=()=>`<button class="brand" aria-label="LinkAge 返回首頁" onclick="if(logged)go('home')"><img class="brand-icon" src="logo.svg?v=arches-10" alt="" width="60" height="40">LinkAge</button>`;
const btn=(text,action,style='')=>`<button class="btn ${style}" onclick="${action}">${typeof text==='string'&&text.startsWith('返回')?'← '+text:text}</button>`;
const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function go(r){stopPreContactAudio();if(r==='newRecord'&&route!=='newRecord')contactDraftKey='';if(['home','cases','analytics'].includes(r)){fromStat=false;fromAnalytics=false;}if(r==='resources'&&route!=='resources'){filters={};resourceSearch=''}route=r;modal='';render();window.scrollTo(0,0)}
let caseOrigin='cases';
function openCase(i=0,tab='overview'){if(!['case','result','newRecord','feedback','feedbackDetail','activityOverview','success'].includes(route))caseOrigin=route;selectedCase=i;records=caseRecords[i]||(caseRecords[i]=[]);caseTab=tab;filters={};onlySuggested=i===0;go('case')}
function tab(t){if(t==='matching'&&caseTab!=='matching'){filters={};resourceSearch=''};caseTab=t;go('case')}
let deletedRecords=[];
const currentUserId='demo-lin';
const currentUser={id:currentUserId,name:'林書含',role:'物理治療師'};
function ownsRecord(r){return logged&&!!r&&(r.createdBy===currentUserId||(!r.createdBy&&r.person==='林書含（物理治療師）'))}
function requestDeleteRecord(){if(!ownsRecord(records[recordIndex])){toast('只有新增者可以刪除這筆紀錄');return}modal='deleteRecord';render()}
function deleteCurrentRecord(){if(!ownsRecord(records[recordIndex]))return;const removed=records.splice(recordIndex,1)[0];deletedRecords.push({caseId:selectedCase,record:removed,index:recordIndex,deletedAt:Date.now(),expiresAt:Date.now()+14*86400000});modal='';recordIndex=0;saveDemo();returnFromRecord();toast('紀錄已移至設定的垃圾桶，十四天內可復原')}
function activeTrash(){return deletedRecords.filter(item=>item.expiresAt>Date.now()&&ownsRecord(item.record))}
function restoreDeletedRecord(i){const item=deletedRecords[i];if(!item||item.expiresAt<=Date.now()||!ownsRecord(item.record)){toast('此紀錄已超過復原期限');render();return}const list=caseRecords[item.caseId]||(caseRecords[item.caseId]=[]);list.splice(Math.min(item.index,list.length),0,item.record);deletedRecords.splice(i,1);saveDemo();render();toast('紀錄已復原，個案與統計已同步')}
let trashSelection=new Set();
function trashPanel(){return `<section class="card gap"><div class="row between"><div><h2>垃圾桶</h2><p class="small space">${activeTrash().length} 筆紀錄 · 刪除後十四天內可復原</p></div>${btn('開啟垃圾桶',"trashSelection.clear();go('trash')",'secondary')}</div></section>`}
function trashItems(){return deletedRecords.map((item,index)=>({item,index})).filter(({item})=>item.expiresAt>Date.now()&&ownsRecord(item.record))}
function toggleTrash(i,checked){if(checked)trashSelection.add(i);else trashSelection.delete(i);render()}
function selectAllTrash(checked){trashSelection.clear();if(checked)trashItems().forEach(({index})=>trashSelection.add(index));render()}
function selectedTrash(){return trashItems().filter(({index})=>trashSelection.has(index))}
function restoreTrashBatch(){const items=selectedTrash();for(const {item} of items){const list=caseRecords[item.caseId]||(caseRecords[item.caseId]=[]);list.splice(Math.min(item.index,list.length),0,item.record)}const chosen=new Set(items.map(({item})=>item));deletedRecords=deletedRecords.filter(item=>!chosen.has(item));trashSelection.clear();saveDemo();render();toast(`已復原 ${items.length} 筆紀錄`)}
function requestPurgeTrash(i=null){if(i!==null){trashSelection.clear();trashSelection.add(i)}if(!selectedTrash().length){toast('請先勾選紀錄');return}modal='purgeTrash';render()}
function purgeTrashBatch(){const chosen=new Set(selectedTrash().map(({item})=>item));deletedRecords=deletedRecords.filter(item=>!chosen.has(item));trashSelection.clear();modal='';saveDemo();render();toast('所選紀錄已永久刪除')}
let trashCategory='all';const unifiedTrashSelection=new Set();
function trash(){const entries=unifiedTrashItems(),count=entries.filter(e=>unifiedTrashSelection.has(e.id)).length;return `${header('垃圾桶','刪除後十四天內可復原；永久刪除後無法復原。',btn('返回設定',"go('settings')",'secondary'))}${trashCategoryTabs()}<section class="card"><div class="row between" style="flex-wrap:wrap"><label><input type="checkbox" aria-label="全選目前分類" ${entries.length&&count===entries.length?'checked':''} ${entries.length?'':'disabled'} onchange="selectUnifiedTrash(this.checked)"> 全選</label><span>已選 ${count} 筆</span><div class="row" style="flex-wrap:wrap">${btn('復原所選項目',"restoreUnifiedTrash()",'secondary')}${btn('永久刪除所選項目',"requestUnifiedTrashPurge()",'secondary')}</div></div><p class="small space">示範資料保存在目前瀏覽器。</p>${entries.length?entries.map(e=>`<article class="settings-row"><label class="row"><input type="checkbox" aria-label="選擇${esc(e.title)}" ${unifiedTrashSelection.has(e.id)?'checked':''} onchange="toggleUnifiedTrash('${e.id}',this.checked)"><span><b>${esc(e.title)}</b><span class="badge" style="margin-left:8px">${e.kind==='records'?'接觸紀錄':e.kind==='resource'?'資源':'申請紀錄'}</span><p class="small">可復原至 ${new Date(e.item.expiresAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})}</p></span></label>${btn('復原',`restoreUnifiedTrash('${e.id}')`,'secondary')}</article>`).join(''):'<p class="muted space">目前分類沒有可復原的項目。</p>'}</section>`}

let recordOrigin={route:'case',tab:'timeline'},feedbackEditing=-1,feedbackCancel='case';
function viewRecord(i,origin=null){recordOrigin=origin||{route,tab:caseTab};recordIndex=i;resultTab='ai';go(records[i].feedback?'feedbackDetail':'result')}
const cname=()=>cases[selectedCase][0];
function crumb(parts=[]){return `<div class="crumb"><button onclick="go('cases')">個案管理</button><span>／</span><button onclick="openCase(${selectedCase})">${esc(cname())}</button>${parts.map(p=>`<span>／</span>${p[1]?`<button onclick="${p[1]}">${p[0]}</button>`:`<span>${p[0]}</span>`}`).join('')}</div>`}
function header(title,sub='',action=''){const back=action.includes('返回'),label=back?(action.match(/>([^<]*返回[^<]*)<\/button>/)?.[1]||'返回').replace(/^←\s*/,''):'';if(back){const arrow=action.replace('<button ',`<button aria-label="${esc(label)}" title="${esc(label)}" `).replace(/>[^<]*返回[^<]*<\/button>/,'>←</button>');return `<div class="intro row" style="gap:16px;align-items:flex-start">${arrow}<div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`}return `<div class="intro row between"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function stats(labels,values,interactive=false){return `<div class="grid four">${labels.map((l,i)=>`${interactive?`<button type="button" class="card stat stat-link" onclick="openStat(${i})" aria-label="${l}，${values[i]}${i===0||i===1?'位':'筆'}，查看明細">`:'<div class="card stat">'}<span class="stat-label">${l}</span><div class="number">${values[i]}<small> ${i===0?'位':''}</small></div><span aria-hidden="true" class="stat-icon ${['','orange','green','pink'][i]}" ${i===0?'style="background:#eee7fa;color:#7350b9"':''}>${i===0?'<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="12" cy="7" r="3.5"/><path d="M5 20v-2a7 7 0 0 1 14 0v2z"/></svg>':statSmallIcon(i)}</span><small>${['持續累積每一次理解','把關心化為下一步行動','連結社區，留下參與結果','下一次接觸時再確認'][i]}</small>${interactive?'<span class="stat-detail-link">查看明細</span></button>':'</div>'}`).join('')}</div>`}

function login(){return `<div class="login"><section class="login-story">${brand()}<div><span class="badge">CONNECT · UNDERSTAND · CARE</span><h1>每一次接觸，<br>都讓理解更靠近。</h1><p>把生活中的點滴串起來，<br>讓陪伴有脈絡，讓參與有可能。</p><div class="login-orbit"><div class="orbit-card"><strong>01</strong><h3>接觸</h3><span>記下每一次真實的交流</span></div><div class="orbit-card"><strong>02</strong><h3>理解</h3><span>看見一個人的生活脈絡</span></div><div class="orbit-card"><strong>03</strong><h3>連結</h3><span>一起找到參與的可能</span></div><div class="orbit-card"><strong>04</strong><h3>陪伴</h3><span>讓回饋成為下一次理解</span></div></div></div><small>為第一線服務人員而設計的陪伴工作平台</small></section><section class="login-form"><div class="login-form-inner">${brand()}<h2>長者社會參與與陪伴追蹤平台</h2><p>讓每一次接觸，都累積成對一個人的理解。</p><form onsubmit="event.preventDefault();logged=true;nextHomeSlogan();go('home')"><label class="field">帳號<input type="email" value="demo@linkage.tw" autocomplete="username"></label><label class="field">密碼<input type="password" value="demodemo" autocomplete="current-password"></label>${btn('登入 LinkAge',"logged=true;nextHomeSlogan();go('home')")}</form><div class="lock">🔒 本系統僅供授權之照護／服務人員使用</div><div class="login-foot">本 Prototype 所有個案、人物與紀錄皆為虛構示範資料。<br>目前可直接進入，無須驗證帳號密碼。</div></div></section></div>`}
function logout(){logged=false;route='home';modal='';render();window.scrollTo(0,0)}
function shell(content){const nav=[['home','首頁'],['cases','個案管理'],['resources','活動資源'],['resourceManagement','資源管理'],['analytics','統計分析'],['settings','設定'],['support','問題回報與建議']];const active=route==='resourceSubmit'?'resourceManagement':route==='applicationResults'?'home':route==='trash'?'settings':route==='analyticsDetail'?'analytics':['case','result','newRecord','feedback','feedbackDetail','activityOverview','success'].includes(route)?'cases':route;return `<aside class="sidebar" id="sidebar">${brand()}<small style="padding:8px 12px">讓每一次接觸，都累積成理解。</small><nav class="nav">${nav.map(([n,l])=>`<button class="${active===n?'active':''}" onclick="go('${n}')">${icon(n==='analytics'?'analytics':n)}${l}</button>`).join('')}</nav><div class="sidebottom">🔒 機構內部系統<br><small>僅限授權人員使用</small><div class="space">${badge('PROTOTYPE · 示範資料')}</div></div></aside><button class="sidebar-backdrop" aria-label="關閉導覽" onclick="closeSidebar()"></button><header class="topbar"><button class="mobile-menu" aria-label="開啟導覽" aria-controls="sidebar" aria-expanded="false" onclick="toggleSidebar()">☰</button><span class="topdate">○○長照服務單位 <span style="padding:0 12px;color:#d9d3e3">／</span> 服務工作平台</span><div class="user">${badge('已登入','green')}${userAvatar()}<div><p><b>林書含</b>　物理治療師</p><small>○○長照服務單位</small></div><button class="logout-btn" onclick="logout()" aria-label="登出 LinkAge">登出</button></div></header><main>${fromAnalytics&&['result','feedbackDetail'].includes(route)?`<div class="crumb"><button onclick="go('analyticsDetail')">返回${analyticsTitles[analyticsKind]}明細</button></div>`:''}${content}<footer class="footer">本 Prototype 所有個案、人物與紀錄皆為虛構示範資料。<br>LinkAge · 讓每一次接觸，都累積成對一個人的理解。</footer></main>${modal?renderModal():''}`}
function home(){return `${header('首頁','每一份關心，都值得被記住。')}<div class="welcome"><div><h2>${esc(homeSlogans[homeSloganIndex])}</h2><p>有 ${followups.length} 位長者在近期等候追蹤，從上一次的對話開始吧。</p></div><div class="dateblock">2026 年 10 月 5 日<br>星期一</div></div>${basicReviewNotices()}${stats(['追蹤個案','7 天內待追蹤','本月成功參與','待確認事項'],[cases.length,followups.length,monthParticipations().length,pendingTasks.length],true)}<div class="grid two gap"><section class="card"><div class="row between section-head"><h2>近期需關注</h2><button class="textbtn" onclick="go('cases')">查看全部</button></div>${cases.map((c,id)=>({c,id})).sort((a,b)=>(b.c[3]===null?Infinity:b.c[3])-(a.c[3]===null?Infinity:a.c[3])||a.id-b.id).slice(0,3).map(({c,id})=>[c[0],c[4],c[3]===null?'尚未接觸':c[3]+' 天前接觸',c[3]===null?'':c[3]>14?'orange':'green',id]).map((a,i)=>`<div class="row between focus-row" style="flex-wrap:wrap;gap:12px"><div class="row" style="flex:1;min-width:180px">${caseAvatar(a[4])}<div style="min-width:0"><div class="row" style="flex-wrap:wrap;gap:8px"><b style="white-space:nowrap">${esc(a[0])}</b>${badge(a[2],a[3])}</div><p>${a[1]}</p></div></div><button class="textbtn" style="white-space:nowrap" onclick="openCase(${a[4]})">查看個案</button></div>`).join('')}</section><section class="card"><span class="badge">關於 LinkAge</span><h2 class="space">LinkAge 在做什麼？</h2><p class="muted space" style="font-size:14px">把分散的接觸紀錄整理成可追蹤的生活脈絡，協助工作人員辨識參與阻礙、媒合社區資源，並記錄實際參與結果。</p><div class="process">${['接觸紀錄','程式摘要','資源媒合','後續追蹤'].map((s,i)=>`<div class="step"><b>${[contactProcessIcon(),'✧',matchingProcessIcon(),'✓'][i]}</b><span>${s}</span></div>`).join('')}</div><div class="callout">「我們明明和這個人接觸過很多次，<br>這些接觸有沒有真的讓我們更理解他？」</div></section></div><div class="card gap row between"><div><h3>從${esc(cases[0][0])}的故事，開始一次完整的服務流程</h3><p class="small">接觸 → 理解 → 行動 → 參與 → 回饋</p></div>${btn('查看'+esc(cases[0][0]),"openCase(0)",'light')}</div>`}
function caseList(){return `${header('個案管理','依最後接觸時間快速掌握待處理事項。',btn('＋ 新增個案',"modal='newCase';render()"))}<div class="lock">🔒 以下僅顯示目前帳號具有服務／查看權限之個案。</div><div class="row between space"><input class="search" aria-label="搜尋個案" placeholder="搜尋姓名、關鍵字……" value="${esc(search)}" oninput="search=this.value;updateCaseRows()"><div class="row" style="flex-wrap:wrap;gap:10px"><small>共 ${cases.length} 位服務個案</small><select aria-label="個案時間排序" style="padding:9px 12px;border:1px solid var(--line);border-radius:8px;background:white" onchange="caseSort=this.value;updateCaseRows();saveViewState()"><option value="oldest" ${caseSort==='oldest'?'selected':''}>↓ 久未接觸優先</option><option value="newest" ${caseSort==='newest'?'selected':''}>↑ 最近接觸優先</option></select></div></div><div class="filters">${['全部','近 7 天','8–14 天','15–30 天','超過 30 天'].map((s,i)=>`<button class="filter ${caseFilter===s?'active':''}" onclick="caseFilter='${s}';render()">${s}（${i===0?cases.length:cases.filter(c=>c[3]!==null&&(i===1?c[3]<=7:i===2?c[3]>=8&&c[3]<=14:i===3?c[3]>=15&&c[3]<=30:c[3]>30)).length}）</button>`).join('')}</div><div class="card tablecard"><table><thead><tr><th>姓名</th><th>年齡</th><th>最後接觸</th><th>距今天數</th><th>待處理事項</th><th>操作</th></tr></thead><tbody id="caseRows">${caseRows()}</tbody></table></div>`}
function caseRows(){const rows=cases.map((c,i)=>({c,i})).filter(({c})=>c.join(' ').includes(search)&& (caseFilter==='全部'||(caseFilter==='近 7 天'?c[3]!==null&&c[3]<=7:caseFilter==='8–14 天'?c[3]>=8&&c[3]<=14:caseFilter==='15–30 天'?c[3]>=15&&c[3]<=30:c[3]>30))).sort((a,b)=>{const ad=a.c[3],bd=b.c[3];if(ad===null&&bd===null)return a.i-b.i;if(ad===null)return caseSort==='oldest'?-1:1;if(bd===null)return caseSort==='oldest'?1:-1;return (caseSort==='oldest'?bd-ad:ad-bd)||a.i-b.i});return rows.length?rows.map(({c,i})=>`<tr class="clickrow" tabindex="0" onclick="openCase(${i})" onkeydown="if(event.key==='Enter')openCase(${i})"><td><div class="namecell">${caseAvatar(i)}${esc(c[0])}</div></td><td>${caseAge(c)} 歲</td><td><button class="textbtn" onclick="event.stopPropagation();editCaseFromList(${i})">${c[2]||'尚未接觸'}</button></td><td><button onclick="event.stopPropagation();editCaseFromList(${i})" aria-label="編輯距今天數">${c[3]===null?badge('—'):badge(c[3]+' 天',c[3]>14?'orange':'green')}</button></td><td><button class="textbtn" onclick="event.stopPropagation();editCaseFromList(${i})">${esc(c[4])}</button></td><td><button class="textbtn" onclick="event.stopPropagation();editCaseFromList(${i})">編輯</button><button class="textbtn" onclick="event.stopPropagation();openCase(${i})">查看</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">沒有符合條件的個案</td></tr>'}
function updateCaseRows(){$('#caseRows').innerHTML=caseRows()}
function profile(){return `<div class="profile"><button class="profile-back" aria-label="${caseBackLabel()}" title="${caseBackLabel()}" onclick="returnFromCase()">‹</button>${caseAvatar(selectedCase)}<div><h1>${esc(cname())} <small style="font-weight:400">${caseAge(cases[selectedCase])} 歲・${caseGenders[selectedCase]||'未填寫'}</small></h1><div class="row space" style="margin-top:7px">${selectedCase===0?badge('獨居')+badge('可自行步行','green')+badge('有慢性病','blue'):badge(records.length?'已有接觸紀錄':'待建立生活脈絡','blue')}</div></div><div class="profilemeta">個案編號 ${caseCode()}<br>初次接觸 ${selectedCase===0?'2026/08/10':(records.at(-1)?.date||'尚無接觸紀錄')}</div></div><div class="tabs">${[['overview','個案首頁'],['timeline','歷次接觸'],['trends','參與趨勢'],['matching','資源媒合'],['files','檔案資料']].map(([t,l])=>`<button class="${caseTab===t?'active':''}" onclick="tab('${t}')">${l}</button>`).join('')}</div>`}
function casePage(){const names={overview:'個案首頁',timeline:'歷次接觸',trends:'參與趨勢',matching:'資源媒合',files:'檔案資料'};return (fromAnalytics?`<div class="crumb"><button onclick="go('analyticsDetail')">返回${analyticsTitles[analyticsKind]}明細</button></div>`:'')+(fromStat?`<div class="crumb"><button onclick="fromStat=false;go('statDetail')">返回${statTitles[statKind]}明細</button></div>`:'')+crumb([[names[caseTab]]])+profile()+(caseTab==='overview'?caseSummary():'')+({overview:caseOverview,timeline,trends:emptyTrends,matching,files}[caseTab])()}
function overview(){const data=basicValues();return `<div class="grid two"><section class="card"><h2>基本資料</h2><dl class="details"><dt>居住地</dt><dd>臺中市西區</dd><dt>聯絡方式</dt><dd>04-2XXX-XXXX</dd><dt>主要照顧者</dt><dd>女兒（白天工作）</dd><dt>就醫狀況</dt><dd>固定回診</dd></dl></section>${[['生活脈絡與興趣','green',['家庭狀況：'+(data.family||'待補充同住家人與聯繫情形'),'以前常去公園下棋','喜歡與鄰居聊天','重視不麻煩家人','朋友退休後較少外出']],['近期變化','pink',['外出頻率下降','近期曾因膝部不適減少活動','願意嘗試熟悉類型的社區活動']],['可能參與阻礙','orange',['對陌生活動有些擔心','缺少熟悉的同行者','交通便利性會影響意願','膝部不適可能降低外出意願']]].map(([t,c,items])=>`<section class="card"><h2><span class="badge ${c}">✧</span> ${t}</h2><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul></section>`).join('')}</div><div class="callout gap">依目前工作紀錄整理，以上為生活資訊與待確認因素，不作醫療診斷。重要資訊仍需與長者共同確認。</div><div class="row between gap"><p class="small">最後更新：2026/10/03 · 林書含</p>${btn('查看歷次接觸',"tab('timeline')")}</div>`}
function otherCase(){return `<div class="grid two"><section class="card"><h2>${esc(cname())}的服務摘要</h2><dl class="details"><dt>個案編號</dt><dd>${caseCode()}</dd><dt>接觸紀錄</dt><dd>${records.length} 筆</dd></dl><div class="space">${btn('新增接觸紀錄',"go('newRecord')")}</div></section><section class="card"><h2>生活脈絡與參與條件</h2>${records.length?`<p class="muted space">${esc(records[0].summary)}</p><p class="small space">依最近一筆接觸紀錄呈現，重要資訊仍待工作人員確認。</p>`:'<p class="muted space">目前尚未記錄興趣、交通需求與可參與時段。</p><p class="small space">可先新增一次接觸，或瀏覽資源後與長者一起確認。</p>'}<div class="space">${btn('為'+esc(cname())+'查看資源',"tab('matching')",'light')}</div></section></div>`}
function timeline(){return `${header('歷次接觸','把每次對話與參與，串成持續的理解。',`<div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px">${btn('＋ 新增接觸紀錄',"go('newRecord')")}${btn('草稿箱（'+contactDrafts.filter(d=>d.caseId===selectedCase).length+'）',"modal='contactDrafts';render()",'secondary')}</div>`)}<div class="timeline">${recordFilterUI('timeline')}${filteredRecords('timeline').length?'':'<div class="card empty">目前沒有符合篩選的紀錄，可清除篩選或新增接觸紀錄。</div>'}${filteredRecords('timeline').map(({r,i})=>`<article class="event"><div class="date">${esc(r.date)}</div><div class="card"><div class="row between"><div><h3>${esc(r.source)}</h3><small>${esc(r.person)}</small></div>${badge(r.status,r.status.includes('已參與')?'green':r.status==='考慮參與'?'orange':'blue')}</div><p>${esc(r.summary)}</p><div class="row between"><small>${r.feedback?'參與結果 · 已寫入個案紀錄':'接觸紀錄 · 依服務權限開放'}</small><button class="textbtn" onclick="viewRecord(${i})">查看</button></div></div></article>`).join('')}</div>`}
const aiSections=[['本次新增資訊',['過去有下棋習慣，且對此有正向感受','近期膝部不適，外出活動減少','對再次參與活動有意願','星期三較不方便']],['與前次相比的變化',['從「有興趣先看看」進一步表達願意再次參與','新增時間偏好','新增距離偏好']],['可能參與阻礙',['膝部不適可能影響外出','活動距離過遠可能降低參與意願','陌生環境可能增加參與門檻']],['低風險協助因子',['熟悉的下棋活動可降低陌生感','鄰近、交通方便的據點較適合優先詢問','若有熟悉的人同行，可能增加首次參與意願']],['下次可確認事項',['確認近期膝部不適是否仍影響外出','確認星期三以外可參與的時段','確認可接受的交通方式與距離','確認是否希望有人陪同第一次參與']]];
function result(){const r=records[recordIndex];let sections=r.aiResult?['本次重點','近期變化','可能參與阻礙','可協助的線索','下次待確認事項'].map((t,i)=>[t,r.aiResult[['highlights','changes','barriers','support','followup'][i]]]):organizeRecord(r,records[recordIndex+1]);return `${crumb([['歷次接觸',"tab('timeline')"],[esc(r.date)]])}${recordOrigin.tab==='files'?'<button class="btn secondary" aria-label="返回檔案資料" onclick="returnFromRecord()">←</button>':''}${header(r.aiResult?'歷史整理結果':'逐字稿整理結果','')}${r.aiError?`<div class="callout space">${esc(r.aiError)}</div>`:''}<div class="row">${caseAvatar(selectedCase)}<div><b>${esc(cname())}</b>　${badge(r.source)}<p class="small">${esc(r.date)}　紀錄者：${esc(r.person)}</p></div></div><div class="segmented"><button class="${resultTab==='ai'?'active':''}" onclick="resultTab='ai';render()">${r.aiResult?'AI 整理紀錄':'程式摘要'}</button><button class="${resultTab==='corrected'?'active':''}" onclick="resultTab='corrected';render()">AI 修正版</button><button class="${resultTab==='raw'?'active':''}" onclick="resultTab='raw';render()">原始逐字稿</button></div>${resultTab==='corrected'?correctedTranscript(r):resultTab==='raw'?`<div class="card"><div class="restricted"><b>🔒 受限資料 · 依角色權限開放</b><p class="small space">正式系統中，原始逐字稿將依角色與服務權限限制存取。</p></div>${r.isDemoTranscript?'<p class="small space">虛構示範逐字稿 · 約五分鐘對話篇幅，非實際錄音轉寫。</p>':''}<p class="transcript">${esc(r.text)}</p></div>`:`<div class="callout" style="margin-bottom:20px">${r.aiResult?'✧ AI 整理草稿 · 待人工核對':'✧ 免費程式摘要 · 不需金鑰或 API 額度'}<br>整理內容待工作人員核對；程式依文字規則產生提示，未辨識的內容不代表原文沒有提到。</div><div class="grid two">${sections.map(([t,items],i)=>`<section class="card ai-card" style="${i===4?'grid-column:1/-1':''}"><span class="ai-num">${i+1}</span><div><h2>${t}</h2><ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div></section>`).join('')}</div>`}<div class="row between gap actions">${recordOrigin.tab==='files'?'':btn(recordBackLabel(),"returnFromRecord()",'secondary')}${ownsRecord(r)?btn('刪除紀錄',"requestDeleteRecord()",'secondary'):''}${btn('前往資源媒合 →',"tab('matching')")}</div>`}
function newRecord(){return `${crumb([['歷次接觸',"tab('timeline')"],['新增接觸紀錄']])}${header('新增接觸紀錄',esc(cname())+' · '+caseCode())}<form class="card formwidth" onsubmit="saveRecord(event)"><div class="formgrid"><label class="field">日期<input id="recDate" type="date" value="${selectedCase===0?'2026-10-03':'2026-10-05'}" required></label><label class="field">紀錄者<input id="recPerson" value="${esc(currentUser.name)}" readonly aria-readonly="true" style="background:var(--bg)"></label><label class="field">專業身分<input id="recRole" value="${esc(currentUser.role)}" readonly aria-readonly="true" style="background:var(--bg)"></label></div><p class="small">紀錄者與專業身分由目前登入帳號帶入。</p><label class="field gap">紀錄來源<select id="recSource" onchange="toggleRecordOther('recSource')">${['現場訪談','電話訪談','其他'].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field" id="recSourceOtherField" hidden>其他紀錄來源<input id="recSourceOther" disabled maxlength="120" placeholder="請填寫紀錄來源，例如：家屬回報" oninput="this.setCustomValidity('')"></label><label class="field gap">本次紀錄類型<select id="recKind" onchange="toggleActivityRecord()"><option value="contact">一般接觸／訪談（含電話關懷）</option><option value="activity">活動參與紀錄</option></select></label><p class="small">一般接觸包含現場訪談、電話關懷等；請在「紀錄來源」選擇實際接觸方式。</p><fieldset id="recActivityFields" class="field" hidden disabled><legend>活動參與</legend><label class="field">選擇活動<select id="recActivity" onchange="toggleRecordActivityOther()">${resources.filter(r=>!r.deletedAt).map(r=>`<option>${esc(r.short||r.name)}</option>`).join('')}<option>其他</option></select></label><label id="recActivityOtherField" class="field" hidden>其他活動<input id="recActivityOther" disabled maxlength="120"></label><label class="field">本次參與狀態<select id="recAttendance"><option>已參與</option><option>有意願參加</option><option>尚未決定</option><option>未參與</option></select></label><label class="field">參與感受／未參與情況<textarea id="recFeeling" required></textarea></label><label class="field">後續參與意願<select id="recWilling"><option>暫不確定</option><option>願意</option><option>不願意</option><option>未填寫</option></select></label><label class="field">原因／需要的協助<textarea id="recReason"></textarea></label><p class="small">只有「已參與」會列入成功參與統計；有意願或尚未決定不計入。</p></fieldset><div class="field gap">輸入方式</div><div class="segmented"><button type="button" class="active" onclick="showInputMode('文字',this)">貼上文字</button><button type="button" onclick="showInputMode('檔案',this)">上傳檔案／逐字稿</button><button type="button" onclick="showInputMode('語音',this)">語音轉文字</button></div><div id="inputExtra"></div><label class="field">接觸內容<textarea id="recText" required placeholder="記錄這次對話：生活近況、興趣、外出意願、方便時段與需要的協助……">${selectedCase===0?baseText:''}</textarea></label><div class="callout gap">程式摘要提供資訊整理與追蹤提示。儲存後會依原文擷取重點；未提及的資訊不補寫。</div><div class="row between gap">${btn('取消',"tab('timeline')",'secondary')}<div class="row"><button class="btn secondary" type="button" onclick="saveContactDraft()">儲存草稿</button><button class="btn" type="submit">儲存紀錄</button></div></div></form>`}
function showInputMode(mode,b){b.parentNode.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#inputExtra').innerHTML=mode==='檔案'?'<label class="field" style="margin-bottom:18px">選擇文字逐字稿（.txt）<input type="file" accept=".txt,text/plain" onchange="readFile(this)"></label>':mode==='語音'?'<div class="callout" style="margin-bottom:18px">Demo 模擬語音轉文字，不使用麥克風。 <button type="button" class="textbtn" onclick="document.querySelector(\'#recText\').value=selectedCase===0?baseText:\'今天聊到喜歡與鄰居交流，希望先了解附近有哪些活動，交通與陪同需求還需要再確認。\';toast(\'已載入示範語音文字\')">載入示範語音文字</button></div>':''}
function readFile(input){let f=input.files[0];if(f)f.text().then(t=>{$('#recText').value=t;toast('已載入文字逐字稿')})}
function toggleActivityRecord(){const active=$('#recKind').value==='activity';$('#recActivityFields').hidden=!active;$('#recActivityFields').disabled=!active;$('#recText').required=!active}
function toggleRecordActivityOther(){const other=$('#recActivity').value==='其他';$('#recActivityOtherField').hidden=!other;$('#recActivityOther').disabled=!other;$('#recActivityOther').required=other}
function saveRecord(e){e.preventDefault();const role=currentUser.role,source=recordChoice('recSource');if(role===null||source===null)return;const text=$('#recText').value,activityMode=$('#recKind').value==='activity',activity=activityMode?($('#recActivity').value==='其他'?$('#recActivityOther').value.trim():$('#recActivity').value):'',attendance=activityMode?$('#recAttendance').value:'',feeling=activityMode?$('#recFeeling').value.trim():'';if(activityMode&&(!activity||!feeling)){toast('請填寫活動名稱與參與情況');return}recordOrigin={route:'case',tab:'timeline'};records.unshift({createdBy:currentUserId,date:$('#recDate').value.replaceAll('-','/'),person:currentUser.name+'（'+role+'）',source,text,summary:organizeRecord({text})[0][1].join('；'),status:'待確認',custom:selectedCase!==0||text.trim()!==baseText,...(activityMode?{feedback:true,activity,source:activity+'參與紀錄',status:attendance,feeling,willing:$('#recWilling').value,reason:$('#recReason').value.trim()||'未填寫',summary:attendance+'。'+feeling}:{})});cases[selectedCase][2]=records[0].date;cases[selectedCase][3]=contactDays($('#recDate').value);recordIndex=0;resultTab='ai';if(contactDraftKey){contactDrafts=contactDrafts.filter(d=>d.key!==contactDraftKey);persistContactDrafts();contactDraftKey=''}saveDemo();go(activityMode?'feedbackDetail':'result');toast('接觸紀錄已儲存');}
function selectFilter(key,label,options,disabled=false){return `<select aria-label="${label}" ${disabled?'disabled':''} onchange="setResourceFilter('${key}',this.value)"><option value="">全部</option>${options.map(v=>`<option ${filters[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function setResourceFilter(key,value){filters[key]=value;if(key==='city'){filters.area='';filters.village=''}if(key==='area')filters.village='';render()}
let filterPanelOpen=false;
function filterUI(context){const villages=[...new Set(resources.filter(r=>(!filters.city||(r.city||'臺中市')===filters.city)&&(!filters.area||r.area===filters.area)).map(r=>r.village).filter(Boolean))],labels={type:'活動類型',city:'縣市',area:'鄉鎮市區',village:'村里',day:'星期',period:'時段',traffic:'交通方式'},active=Object.entries(filters).filter(([key,value])=>value&&labels[key]),field=(key,options,disabled=false)=>`<label class="resource-filter-field"><span>${labels[key]}</span>${selectFilter(key,labels[key],options,disabled)}</label>`;return `<section class="resource-filter-box"><div class="resource-filter-toolbar"><span class="small">${active.length?'已選 '+active.length+' 個條件':'依需求縮小搜尋範圍'}</span>${active.length?btn('清除條件',"filters={};render()",'secondary'):''}${context?`<label class="toggle"><input type="checkbox" ${onlySuggested?'checked':''} onchange="onlySuggested=this.checked;render()">僅顯示建議</label>`:''}</div>${active.length?`<div class="filter-chips">${active.map(([key,value])=>`<button type="button" onclick="setResourceFilter('${key}','')" aria-label="移除${labels[key]}：${esc(value)}">${labels[key]}：${esc(value)} <span aria-hidden="true">×</span></button>`).join('')}</div>`:''}<details ${filterPanelOpen?'open':''} ontoggle="filterPanelOpen=this.open"><summary>篩選條件${active.length?' · '+active.length:''}<span class="small">展開／收合</span></summary><div class="resource-filter-groups"><fieldset><legend>活動</legend>${field('type',['棋藝','共餐','健走','手作','歌唱','其他'])}</fieldset><fieldset><legend>地點</legend><div class="resource-filter-fields">${field('city',Object.keys(taiwanDistricts))}${field('area',taiwanDistricts[filters.city]||[],!filters.city)}${field('village',villages,!villages.length)}</div><p class="small">先選縣市，再選鄉鎮市區；村里依已登錄資源提供。</p></fieldset><fieldset><legend>時間與交通</legend><div class="resource-filter-fields">${field('day',['週一','週二','週三','週四','週五','週六','週日'])}${field('period',['早上','下午','晚上'])}${field('traffic',['步行','公車','接送'])}</div></fieldset></div></details></section><p class="small resource-sort-note">活動按開始時間由早到晚排列。</p>`}

function resourcePeriod(r){const hour=Number(r.time.slice(0,2));return hour<12?'早上':hour<18?'下午':'晚上'}
function resourceFilterMatches(r){return Object.entries(filters).every(([k,v])=>!v||(k==='city'?(r.city||'臺中市')===v:k==='period'?resourcePeriod(r)===v:k==='village'?(r.village||'')===v:String(r[k]||'').includes(v)))}

function matching(){const suggestions=suggestedResources();return `${caseActivitySummary()}${header('適合'+esc(cname())+'的活動／資源','依目前紀錄中的興趣、參與條件與待確認因素，提供工作人員優先查看的資源。')}${selectedCase===0?`<div class="row">${badge('興趣：下棋')}${badge('時間：避開星期三','blue')}${badge('距離：希望不要太遠','green')}</div>`:`<div class="callout">${suggestions.length?'依接觸文字中的活動關鍵字提供示範篩選；適合程度、時間與交通仍待確認。':'目前興趣與參與條件尚待確認。可先瀏覽全部資源，再與'+esc(cname())+'討論。'}</div>`}${resourceSearchUI(true)}${filterUI(true)}<div id="resourceList">${resourceList(true)}</div><div class="callout gap">以上供工作人員進一步確認。最後決策由工作人員與長者共同討論。</div>`}
function resourceSearchUI(context){return `<label class="resource-search"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" class="search" placeholder="搜尋活動、地點或關鍵字，例如：圍棋、散步" aria-label="搜尋活動資源" value="${esc(resourceSearch)}" oninput="resourceSearch=this.value;document.querySelector('#resourceList').innerHTML=resourceList(${context})"></label>`}
function resourcePage(){return `${header('活動資源','瀏覽社區資源庫，為下一次連結準備更多可能。')}${resourceSearchUI(false)}${filterUI(false)}<div id="resourceList">${resourceList(false)}</div>`}
function resourceMatches(r,query){const normalize=t=>t.normalize('NFKC').toLowerCase().replaceAll('台','臺');const groups={棋藝:['棋','棋藝','奇藝','圍棋','围棋','象棋','西洋棋','國際象棋','国际象棋','下棋'],共餐:['共餐','吃飯','吃饭','餐食','用餐'],健走:['健走','散步','走路','步行運動'],手作:['手作','手工','DIY','diy'],歌唱:['歌唱','唱歌','卡拉OK','卡拉ok']};const text=normalize([r.name,r.tags.join(' '),r.place,r.day,r.time,r.traffic,r.type,r.desc].join(' '));return normalize(query).trim().split(/\s+/).every(term=>text.includes(term)||(groups[r.type]||[]).some(word=>normalize(word)===term))}
function resourceList(context){let list=resources.map((r,i)=>({r,i})).filter(({r,i})=>(!context||!onlySuggested||resourceSearch.trim()||suggestedResources().includes(i))&&(!resourceSearch.trim()||resourceMatches(r,resourceSearch))&&resourceFilterMatches(r)&&!r.deletedAt).sort((a,b)=>a.r.time.localeCompare(b.r.time)||a.r.name.localeCompare(b.r.name));return list.length?`<div class="grid">${list.map(({r,i})=>`<article class="card resource"><div><div class="row between"><span class="resource-icon">${resourceIcon(r)}</span>${context?badge(isTracked(i)?'追蹤中':suggestedResources().includes(i)?'建議優先查看':'待確認適合度',isTracked(i)?'green':''):badge('社區資源','blue')}</div><h2>${esc(r.name)}</h2><div class="row">${r.tags.map(t=>badge(t)).join('')}</div>${resourceSearch.trim()&&r.type==='棋藝'?'<p class="small space">棋藝類相關結果；實際提供的棋種請向據點確認。</p>':''}<dl class="details"><dt>地點</dt><dd>${esc(r.place)}</dd><dt>時間</dt><dd>${esc(r.day)} ${esc(r.time)}</dd><dt>交通</dt><dd>${esc(r.traffic)}</dd><dt>費用</dt><dd>${esc(r.fee||'免費')}</dd></dl><div class="resource-actions">${btn('查看詳情',`selectedResource=${i};modal='resource';render()`,'secondary')}${!context?btn('提出修改建議',`startResourceEdit(${i})`,'secondary'):''}${context?(isTracked(i)?btn('新增參與回饋',`startFeedback(${i})`):btn('加入追蹤',`selectedResource=${i};modal='track';render()`)):''}</div></div><div class="resource-side"><h3>${context&&suggestedResources().includes(i)?'為什麼建議優先查看？':'資源介紹'}</h3>${context&&selectedCase===0&&i===0?'<ul><li>✓ 與過去下棋興趣相符</li><li>✓ 時間避開星期三</li><li>✓ 希望路程不要太遠，交通與距離待確認</li><li>✓ 有其他長者共同參與</li></ul>':context&&suggestedResources().includes(i)&&demoCaseProfiles[selectedCase-1]?`<ul><li>與紀錄中的興趣相關：${esc(demoCaseProfiles[selectedCase-1].interest)}</li><li>下次需確認：${esc(demoCaseProfiles[selectedCase-1].barrier)}</li></ul><p class="small">依關鍵字提供候選資源，交通、距離與適合程度尚未自動驗證。</p>`:`<p class="muted space" style="font-size:14px">${esc(r.desc)}</p>`}<div class="callout gap">${context?'可能符合目前條件，參與意願與安排仍待確認。':'服務人員可依個案興趣與條件進一步確認。'}</div></div></article>`).join('')}</div>`:'<div class="card empty">沒有符合條件的活動，請換個關鍵字或調整篩選。</div>'}
function startFeedback(resourceId,edit=false){selectedResource=resourceId;feedbackEditing=edit?recordIndex:-1;feedbackCancel=route==='feedbackDetail'?'feedbackDetail':'case';if(route!=='feedbackDetail')recordOrigin={route:route==='activityOverview'?'activityOverview':'case',tab:caseTab};go('feedback')}
function feedbackResource(){const r=records[recordIndex];return resources.findIndex(resource=>resource.short===(r.activity||r.source.replace(/參與回饋$/,'')))}
function startDetailFeedback(edit){const id=feedbackResource();if(id<0){toast('找不到對應活動資源');return}startFeedback(id,edit)}
function recordBackLabel(){if(recordOrigin.tab==='files')return '←';return recordOrigin.route==='analyticsDetail'?'返回統計明細':recordOrigin.route==='statDetail'?'返回參與明細':recordOrigin.route==='activityOverview'?'返回活動總覽':recordOrigin.tab==='matching'?'返回資源媒合':recordOrigin.tab==='trends'?'返回參與趨勢':'返回歷次接觸'}
function returnFromRecord(){if(recordOrigin.route==='case')tab(recordOrigin.tab||'timeline');else go(recordOrigin.route)}
function cancelFeedback(){if(feedbackCancel==='feedbackDetail')go('feedbackDetail');else returnFromRecord()}
function feedback(){const r=feedbackEditing>=0?records[feedbackEditing]:null;return `${header(r?'編輯參與回饋':'新增參與回饋',esc(cname())+' · '+esc(r?.activity||resources[selectedResource].name),btn(feedbackCancel==='feedbackDetail'?'返回參與回饋':recordBackLabel(),"cancelFeedback()",'secondary'))}<form class="card formwidth" onsubmit="saveFeedback(event)"><label class="field">參與日期<input type="date" id="fbDate" value="${r?r.date.replaceAll('/','-'):'2026-10-05'}" required></label><div class="field gap">是否參與<div class="radio">${[['yes','已參與'],['no','未參與'],['intent','有意願參加'],['undecided','尚未決定']].map(([v,label])=>`<label><input type="radio" name="attended" value="${v}" ${(r?({'已參與':'yes','未參與':'no','有意願參加':'intent','尚未決定':'undecided'}[r.status]||'no'):'yes')===v?'checked':''}> ${label}</label>`).join('')}</div></div><label class="field gap">參與後感受<textarea id="fbFeeling" required placeholder="請填寫參與感受或未參與的情況……">${esc(r?.feeling||'')}</textarea></label><div class="field gap">是否願意繼續<div class="radio">${['願意','暫不確定','不願意','未填寫'].map(v=>`<label><input type="radio" name="continue" value="${v}" ${(r?.willing||'未填寫')===v?'checked':''}> ${v}</label>`).join('')}</div></div><label class="field gap">主要原因<textarea id="fbReason" placeholder="參與或未參與的原因、希望獲得的協助……">${esc(r?.reason==='未填寫'?'':r?.reason||'')}</textarea></label><div class="row between gap">${btn('取消',"cancelFeedback()",'secondary')}<button class="btn" type="submit">${r?'儲存修改':'儲存參與回饋'}</button></div></form>`}
function saveFeedback(e){e.preventDefault();const feeling=$('#fbFeeling').value.trim();if(!feeling){$('#fbFeeling').setCustomValidity('請填寫參與回饋');$('#fbFeeling').reportValidity();$('#fbFeeling').oninput=function(){this.setCustomValidity('')};return}const attendance=$('input[name="attended"]:checked').value,attended=attendance==='yes',participationStatus={yes:'已參與',no:'未參與',intent:'有意願參加',undecided:'尚未決定'}[attendance],willing=$('input[name="continue"]:checked').value,reason=$('#fbReason').value.trim(),old=feedbackEditing>=0?records[feedbackEditing]:null;const r={...(old||{}),createdBy:old?.createdBy||(old?undefined:currentUserId),date:$('#fbDate').value.replaceAll('-','/'),person:old?.person||'林書含（物理治療師）',source:old?.source||resources[selectedResource].short+'參與回饋',activity:old?.activity||resources[selectedResource].short,summary:participationStatus+'。'+feeling+' 繼續參與意願：'+willing,status:participationStatus,feedback:true,feeling,willing,reason:reason||'未填寫'};if(old){records[feedbackEditing]=r;recordIndex=feedbackEditing}else{records.unshift(r);recordIndex=0}feedbackEditing=-1;syncParticipationIndex();saveDemo();go('feedbackDetail');toast(old?'回饋已修改，參與統計已同步':'回饋已新增，參與統計已同步')}
function success(){return `${crumb([['資源媒合',"tab('matching')"],['參與回饋']])}<div class="card success"><div class="success-icon">✓</div><h1>參與結果已加入${esc(cname())}的歷次紀錄。</h1><p class="muted space">這次參與，會成為下一次理解${esc(cname())}的新資訊。</p><div class="gap">${btn('返回'+esc(cname())+'歷次接觸',"tab('timeline')")}</div></div>`}
function feedbackDetail(){const r=records[recordIndex];return `${recordOrigin.tab==='files'?'<button class="btn secondary" aria-label="返回檔案資料" onclick="returnFromRecord()">←</button>':''}${header(r.source,esc(cname())+' · '+r.date,`<div class="row">${btn('編輯回饋',"startDetailFeedback(true)",'secondary')}${ownsRecord(r)?btn('刪除紀錄',"requestDeleteRecord()",'secondary'):''}${btn('新增回饋',"startDetailFeedback(false)")}</div>`)}<div class="space">${recordOrigin.tab==='files'?'':btn(recordBackLabel(),"returnFromRecord()",'secondary')}</div><div class="card gap"><div class="row between">${badge(r.status,r.status==='已參與'?'green':'red')}${badge('繼續參與：'+(r.willing||'未填寫'),r.willing==='願意'?'green':r.willing==='不願意'?'red':r.willing==='暫不確定'?'orange':'gray')}</div><dl class="details"><dt>參與後感受</dt><dd>${esc(r.feeling)}</dd><dt>繼續參與意願</dt><dd>${esc(r.willing)}</dd><dt>主要原因</dt><dd>${esc(r.reason)}</dd></dl><div class="callout gap">請依這筆參與回饋，與本人確認後續安排。</div></div>`}

function bars(labels,values,max=20){return `<div class="chart">${labels.map((l,i)=>`<div class="bar" style="height:${values[i]/max*85}%"><span>${values[i]}</span><label>${l}</label></div>`).join('')}</div>`}
function trends(){return `<div class="grid two"><section class="card"><h2>近幾個月外出／社會參與情形</h2><p class="small">依服務接觸紀錄整理的相對變化</p><div class="chart">${[['7 月','較頻繁',85],['8 月','普通',60],['9 月','下降',30],['10 月','開始恢復',65]].map(([m,s,h])=>`<div class="bar" style="height:${h}%"><span>${s}</span><label>${m}</label></div>`).join('')}</div></section><section class="card"><h2>從紀錄中看見的轉變</h2><ul><li>7 月：仍會外出與鄰居交流</li><li>8 月：外出情形較為普通</li><li>9 月：提到膝部不適，較少出門</li><li>10 月：參與棋藝活動，表達再次參與意願</li></ul><div class="callout gap">本區呈現服務紀錄中的生活與參與變化，不作醫療診斷。</div></section></div>`}
let recordFilters={timeline:{keyword:'',start:'',end:''},files:{keyword:'',start:'',end:''}};
function recordFilterUI(kind){const f=recordFilters[kind];return `<form class="filters space" onsubmit="event.preventDefault();applyRecordFilters('${kind}')"><label class="field">搜尋關鍵字<input id="${kind}_keyword" type="search" placeholder="搜尋紀錄內容、來源或紀錄者" value="${esc(f.keyword)}"></label><label class="field">起始日期<input id="${kind}_start" type="date" value="${f.start}"></label><label class="field">結束日期<input id="${kind}_end" type="date" value="${f.end}"></label><button class="btn" type="submit">搜尋／篩選</button>${btn('清除篩選',`recordFilters.${kind}={keyword:'',start:'',end:''};render()`,'secondary')}</form>`}
function applyRecordFilters(kind){const start=$('#'+kind+'_start').value,end=$('#'+kind+'_end').value;if(start&&end&&start>end){toast('起始日期不能晚於結束日期');return}recordFilters[kind]={keyword:$('#'+kind+'_keyword').value.trim(),start,end};render()}
function filteredRecords(kind){const f=recordFilters[kind];return records.map((r,i)=>({r,i})).filter(({r})=>{const d=r.date.replaceAll('/','-');return (!f.start||d>=f.start)&&(!f.end||d<=f.end)&&(!f.keyword||[r.text,r.summary,r.source,r.person,r.activity].join(' ').includes(f.keyword))})}
function files(){const items=filteredRecords('files');return `${healthFilesSlot()}<div class="card"><h2>檔案資料</h2>${recordFilterUI('files')}<div class="settings-row"><div><h3>基本資料摘要</h3><p>個案編號 ${caseCode()}</p></div>${btn('查看',"modal='file';render()",'secondary')}</div><p class="small space">符合篩選：${items.length} 筆紀錄</p>${items.map(({r,i})=>`<div class="settings-row"><div><h3>${esc(r.date)} ${esc(r.source)}</h3><p>${esc(r.person)}</p></div>${btn('查看',`viewRecord(${i},{route:'case',tab:'files'})`,'secondary')}</div>`).join('')}${items.length?'':'<p class="space">此範圍沒有符合的紀錄。</p>'}</div>`}

let analyticsKind=0,fromAnalytics=false;
const analyticsTitles=['本月有紀錄個案數','追蹤資源筆數','實際參與人數','重複參與人數'];
function analyticsGroups(kind){const groups=[];for(let id=0;id<cases.length;id++){const list=caseRecords[id]||[],attended=list.filter(r=>r.feedback&&r.status==='已參與'&&r.date.startsWith('2026/10/'));if(kind===0){const current=list.filter(r=>r.date?.startsWith('2026/10/'));if(current.length)groups.push({id,records:current})}else if(kind===1){for(const resourceId of (caseTracks[id]||[]))if(resources[resourceId])groups.push({id,resourceId,records:[]})}else if(attended.length>=(kind===3?2:1))groups.push({id,records:attended})}return groups}
function openAnalytics(kind){analyticsCaseFilter='';analyticsTypeFilter='';analyticsKind=kind;fromStat=false;fromAnalytics=false;go('analyticsDetail')}
function openAnalyticsCase(id,record=-1){fromStat=false;fromAnalytics=true;openCase(id,record<0?'overview':'timeline');if(record>=0)viewRecord(record,{route:'analyticsDetail'})}
function analytics(){const counts=analyticsTitles.map((_,i)=>analyticsGroups(i).length);return `${header('統計分析','依個案紀錄計算 · 2026 年 10 月示範資料')}<div class="grid four">${analyticsTitles.map((label,i)=>`<button class="card stat stat-link" onclick="openAnalytics(${i})" aria-label="${label}，${counts[i]}${i===1?'筆':'位'}，查看明細"><span class="stat-label">${label}</span><div class="number">${counts[i]}<small> ${i===1?'筆':'位'}</small></div><small>${['查看本月有紀錄的個案與紀錄者','查看哪位個案追蹤哪些資源','查看實際參與的個案與活動','查看本月至少參與兩次的個案'][i]}</small><span class="stat-detail-link">查看明細 →</span></button>`).join('')}</div><section class="card gap"><h2>本月參與紀錄</h2><p class="space">${monthParticipations().length} 筆實際參與紀錄，涉及 ${counts[2]} 位個案。</p><p class="small space">重複參與人數以同一個案本月至少兩筆已參與紀錄計算；未參與回饋不計入。追蹤資源僅代表已加入追蹤，尚不代表成功媒合或實際參與。</p>${btn('查看參與明細',"openAnalytics(2)",'light')}</section>`}
function analyticsActivityType(r){const text=r.activity||r.source||'';return resources.find(x=>text.includes(x.short||x.name))?.type||(['棋藝','共餐','健走','手作','歌唱'].find(t=>text.includes(t))||'一般接觸')}
function analyticsDetail(){const all=analyticsGroups(analyticsKind),types=[...new Set(all.flatMap(g=>analyticsKind===1?[resources[g.resourceId].type]:g.records.map(analyticsActivityType)))],groups=all.filter(g=>!analyticsCaseFilter||String(g.id)===analyticsCaseFilter).map(g=>({...g,records:analyticsKind===1?g.records:g.records.filter(r=>!analyticsTypeFilter||analyticsActivityType(r)===analyticsTypeFilter)})).filter(g=>analyticsKind===1?(!analyticsTypeFilter||resources[g.resourceId].type===analyticsTypeFilter):g.records.length),ids=[...new Set(all.map(g=>g.id))];return `<div class="crumb"><button onclick="go('analytics')">統計分析</button><span>／</span><span>${analyticsTitles[analyticsKind]}</span></div>${header(analyticsTitles[analyticsKind],'2026 年 10 月 · Prototype 示範資料',btn('返回統計分析',"go('analytics')",'secondary'))}<section class="card analytics-filters"><label class="field">個案姓名<select onchange="analyticsCaseFilter=this.value;render()"><option value="">全部個案</option>${ids.map(id=>`<option value="${id}" ${analyticsCaseFilter===String(id)?'selected':''}>${esc(cases[id][0])}</option>`).join('')}</select></label><label class="field">活動類型<select onchange="analyticsTypeFilter=this.value;render()"><option value="">全部類型</option>${types.map(t=>`<option ${analyticsTypeFilter===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>${btn('清除篩選',"analyticsCaseFilter='';analyticsTypeFilter='';render()",'secondary')}</section><p class="small space">顯示 ${analyticsKind===1?groups.length:new Set(groups.map(g=>g.id)).size} ${analyticsKind===1?'筆追蹤':'位個案'}／全部 ${all.length} ${analyticsKind===1?'筆追蹤':'位個案'}${analyticsKind===3?' · 重複參與以本月至少兩筆已參與紀錄計算，篩選只影響顯示':''}</p><div class="analytics-list">${groups.length?groups.map(g=>`<section class="card"><div class="row between"><div><h2>${esc(cases[g.id][0])}</h2><p class="small">${analyticsKind===1?'追蹤資源 · 尚未代表實際參與':g.records.length+' 筆符合條件的紀錄'}</p></div>${btn('查看個案',`openAnalyticsCase(${g.id})`,'light')}</div>${analyticsKind===1?`<h3>${esc(resources[g.resourceId].name)}</h3><p class="small">${esc(resources[g.resourceId].type)} · ${esc(resources[g.resourceId].place)}</p>${btn('查看資源媒合',`openAnalyticsCase(${g.id});tab('matching')`,'secondary')}`:g.records.map(r=>`<details class="analytics-record"><summary><span>${esc(r.date)}</span><b>${esc(r.activity||r.source)}</b><span class="badge ${r.status==='已參與'?'green':'blue'}">${esc(r.status)}</span><span class="small">展開內容</span></summary><div><p class="small">紀錄者：${esc(r.person)}</p><p>${esc(r.feeling||r.summary)}</p>${btn('查看原始紀錄',`openAnalyticsCase(${g.id},${caseRecords[g.id].indexOf(r)})`,'secondary')}</div></details>`).join('')}</section>`).join(''):'<div class="card empty">沒有符合目前條件的紀錄，可清除篩選查看全部。</div>'}</div>`}



function settings(){return `${header('設定','讓服務協作與資料使用保有清楚的邊界。')}<div class="grid two"><div class="card"><div class="row between"><h2>機構與使用者</h2><label class="avatar-picker" title="更換頭像">${userAvatar()}<span class="small">更換頭像</span><input type="file" accept="image/jpeg,image/png,image/webp" aria-label="上傳個人頭像" onchange="uploadUserPhoto(this)" style="position:absolute;width:1px;height:1px;opacity:0"></label></div>${userPhoto?`<button class="textbtn small" onclick="removeUserPhoto()">移除照片</button>`:''}<dl class="details"><dt>機構名稱</dt><dd>○○長照服務單位</dd><dt>使用者</dt><dd>林書含</dd><dt>專業身分</dt><dd>物理治療師</dd></dl><div class="gap">${btn('登出 LinkAge',"logout()",'secondary')}</div></div><div class="card"><h2>通知設定</h2>${[['追蹤事項提醒','提醒近期待確認與未完成事項'],['參與結果提醒','收到個案新的參與回饋時提示']].map(([s,d],i)=>`<div class="settings-row"><div><h3>${s}</h3><p>${d}</p></div><input class="switch" type="checkbox" aria-label="${s}" ${prefs[i]?'checked':''} onchange="updateNotification(${i},this.checked)"></div>`).join('')}</div><div class="card"><h2>整理與審核流程</h2><p class="space">程式摘要 → 工作人員核對 → 確認後更新個案資料。</p><p class="small space">AI 服務已停用，目前使用免費程式摘要。</p><div class="callout gap">整理結果先供核對；確認內容正確後，再更新個案資料。</div></div><div class="card"><h2>資料與隱私設定</h2><div class="restricted gap">🔒 僅限授權人員 · 依角色權限開放</div><p class="muted" style="font-size:14px">正式系統將依所屬機構、服務關係及角色權限限制個案資料存取。</p><p class="small space">登入身分 → 所屬機構 → 角色權限 → 授權個案</p></div></div>${trashPanel()}`}
let prefs=[true,true];try{const savedPrefs=JSON.parse(demoLocalStorage.getItem('linkage-notification-prefs')||'null');if(Array.isArray(savedPrefs)&&savedPrefs.length===2)prefs=savedPrefs.map(Boolean)}catch(e){}
function updateNotification(i,value){prefs[i]=value;try{demoLocalStorage.setItem('linkage-notification-prefs',JSON.stringify(prefs));toast('通知設定已更新')}catch(e){toast('通知設定未能儲存')}}
function renderModal(){const r=resources[selectedResource];let body=modal==='unifiedTrashPurge'?unifiedTrashPurgeDialog():modal==='contactDrafts'?contactDraftList():modal==='deleteContactDraft'?contactDraftDeleteDialog():modal==='clearReviewResults'?clearReviewResultsDialog():modal==='resourceAction'?resourceActionDialog():modal==='deleteResourceDraft'?resourceDraftDeleteConfirmation():modal==='resourceReview'?resourceReviewView():modal==='confirmResourceApprove'?resourceReviewConfirm(true):modal==='confirmResourceReject'?resourceReviewConfirm(false):modal==='applicationResult'?applicationResultDetail():modal==='confirmApproveBasic'?basicReviewConfirmation(true):modal==='confirmRejectBasic'?basicReviewConfirmation(false):modal==='basicHistory'?basicHistoryView():modal==='purgeTrash'?`<h2>確認永久刪除 ${selectedTrash().length} 筆紀錄嗎？</h2><p class="small space">永久刪除後無法復原。</p><ul>${selectedTrash().map(({item})=>`<li>${esc(cases[item.caseId]?.[0])} · ${esc(item.record.date)} · ${esc(item.record.source)}</li>`).join('')}</ul><div class="row between gap">${btn('取消',"modal='';render()",'secondary')}${btn('確認永久刪除',"purgeTrashBatch()")}</div>`:modal==='deleteRecord'?`<h2>確認要刪除本次紀錄嗎？</h2><p class="space">${esc(records[recordIndex].date)} · ${esc(records[recordIndex].source)}</p><p class="small">刪除後十四天內仍可至設定的垃圾桶內復原。</p><div class="row between gap">${btn('取消',"modal='';render()",'secondary')}${btn('確認刪除',"deleteCurrentRecord()")}</div>`:modal==='editBasic'?basicForm():modal==='reviewBasic'?basicReviewForm():modal==='editSummary'?editSummaryForm():modal==='track'?`<h2>加入${esc(cname())}的追蹤項目</h2><p class="muted space">${esc(r.name)}</p><h3 class="gap">待確認</h3><ul><li>是否願意參加</li><li>交通安排</li><li>是否需要首次陪同</li></ul><div class="row between gap">${btn('取消',"modal='';render()",'secondary')}${btn('建立參與追蹤',"createTracking()")}</div>`:modal==='resource'?`<h2>${esc(r.name)}</h2><p class="muted space">${esc(r.desc)}</p><dl class="details"><dt>地點</dt><dd>${esc(r.place)}</dd><dt>時間</dt><dd>${esc(r.day)} ${esc(r.time)}</dd><dt>費用</dt><dd>${esc(r.fee||'免費')}</dd><dt>聯絡方式</dt><dd>${esc(r.contact||'04-2XXX-XXXX（示範）')}</dd></dl><div class="callout gap">參與前，請進一步確認名額、交通安排與首次陪同需求。</div><div class="gap">${btn('關閉',"modal='';render()",'secondary')}</div>`:modal==='newCase'?`<h2>新增示範個案</h2><form onsubmit="addCase(event)"><label class="field">個案頭像（選填）<input type="file" accept="image/jpeg,image/png,image/webp" onchange="prepareNewCasePhoto(this)"></label><input id="newCasePhotoValue" type="hidden" value=""><img id="newCasePhotoPreview" alt="新個案頭像預覽" style="display:none;width:80px;height:80px;border-radius:50%;object-fit:cover"><button class="textbtn" type="button" onclick="if(!newCasePhotoBusy){document.querySelector('#newCasePhotoValue').value='';document.querySelector('#newCasePhotoPreview').style.display='none'}">移除頭像</button><p class="small">JPG、PNG 或 WebP，10 MB 以下；未上傳時使用預設頭像。</p><label class="field">姓名<input id="caseName" required placeholder="請輸入示範姓名"></label><label class="field">生日<input id="caseBirthday" type="date" min="1900-01-01" max="${localToday()}" required oninput="updateBirthdayAge()"></label><label class="field">年齡（自動計算實歲）<input id="caseAge" readonly placeholder="輸入生日後自動顯示"></label><p class="small">年齡依今天與生日計算；尚未過生日則不加一歲。</p><label class="field">性別<select id="caseGender"><option>男性</option><option>女性</option><option>未填寫</option></select></label><label class="field">最後接觸日期（可留空）<input id="editContactDate" type="date" max="2026-10-05" onchange="syncContactDays()"></label><label class="field">距今天數<input id="editContactDays" type="number" min="0" step="1" placeholder="尚未接觸" oninput="syncContactDate()"></label>${taskFields('安排初次訪視')}<div class="row between gap">${btn('取消',"modal='';render()",'secondary')}<button class="btn" type="submit">新增個案</button></div></form>`:basicFileSummary();return `<div class="modal-bg" onclick="if(event.target===this&&modal!=='editBasic'){modal='';render()}"><section class="card modal" role="dialog" aria-modal="true" aria-label="${modal==='newCase'?'新增個案':'活動與個案資料'}">${body}</section></div>`}
function taskFields(value=''){const chosen=value.split('；').filter(Boolean),custom=chosen.filter(t=>!taskOptions.includes(t));return `<fieldset class="field"><legend>待確認事項（可複選）</legend><div class="gap">${taskOptions.map(t=>`<label style="display:block;margin:10px 0"><input type="checkbox" name="caseTasks" value="${esc(t)}" ${chosen.includes(t)?'checked':''}> ${t}</label>`).join('')}<label style="display:block;margin:10px 0"><input type="checkbox" id="taskOther" ${custom.length?'checked':''} onchange="toggleOtherTask(this.checked)"> 其他（可填多項）</label></div></fieldset><label class="field" id="otherTaskField" ${custom.length?'':'hidden'}>其他待確認事項（每行一項）<textarea id="caseTaskOther" rows="4" ${custom.length?'required':'disabled'} placeholder="例如：&#10;確認餐食偏好&#10;詢問輔具需求" maxlength="2000">${esc(custom.join('\n'))}</textarea><small>可填多項，每行一項；也支援用分號分隔。</small></label>`}
function toggleOtherTask(other){$('#otherTaskField').hidden=!other;$('#caseTaskOther').disabled=!other;$('#caseTaskOther').required=other;if(other)$('#caseTaskOther').focus()}
function readCaseTasks(){const values=Array.from(document.querySelectorAll('input[name="caseTasks"]:checked'),el=>el.value);if($('#taskOther').checked)values.push(...$('#caseTaskOther').value.split(/[；;\n]/).map(t=>t.trim()).filter(Boolean));return [...new Set(values)].join('；')}
function addCase(e){e.preventDefault();if(newCasePhotoBusy){toast('頭像處理中，請稍候');return}if(ageFromBirthday($('#caseBirthday').value)===null){$('#caseBirthday').setCustomValidity('請輸入有效且不晚於今天的生日');$('#caseBirthday').reportValidity();$('#caseBirthday').oninput=function(){this.setCustomValidity('');updateBirthdayAge()};return}const task=readCaseTasks();if(!task){$('#caseTaskOther').setCustomValidity('請填寫其他待處理事項');$('#caseTaskOther').reportValidity();$('#caseTaskOther').oninput=function(){this.setCustomValidity('')};return}const contact=$('#editContactDate').value;cases.push([$('#caseName').value.trim(),ageFromBirthday($('#caseBirthday').value),contact?contact.replaceAll('-','/'):'',contact?contactDays(contact):null,task,$('#caseBirthday').value]);caseGenders.push($('#caseGender').value);caseRecords[cases.length-1]=[];caseBasics[cases.length-1]={name:$('#caseName').value.trim(),photo:$('#newCasePhotoValue')?.value||''};pendingTasks.push({caseId:cases.length-1,task,note:'新增個案待處理事項，請於下次接觸確認。'});saveDemo();modal='';search='';caseFilter='全部';render();toast('已新增示範個案')}

let statKind=0,fromStat=false;
const statTitles=['追蹤個案','7 天內待追蹤','本月成功參與','待確認事項'];
const followups=[{caseId:0,due:'2026/10/06',task:'確認下次棋藝活動時間'},{caseId:1,due:'2026/10/07',task:'確認參與活動的交通方式'},{caseId:5,due:'2026/10/08',task:'確認首次參與的陪同人選'},{caseId:6,due:'2026/10/09',task:'電話詢問社區共餐意願'}];
const pendingTasks=[{caseId:0,task:'確認下次活動時間',note:'詢問星期三以外方便的時段。'},{caseId:1,task:'確認交通方式',note:'了解是否需要接送或熟悉的人同行。'},{caseId:2,task:'補上後續接觸紀錄',note:'再次聯繫，記下近期生活與參與意願。'},{caseId:3,task:'評估居家支持需求',note:'詢問目前生活中希望獲得的協助。'},{caseId:4,task:'安排再次訪視',note:'確認方便聯繫與訪視的時間。'},{caseId:5,task:'確認陪同人選',note:'詢問是否希望有人陪同首次參與。'}];
const participations=[{caseId:0,date:'2026/10/03',activity:'長者棋藝活動',feeling:'認識新的棋友，表示願意再次參與。'},{caseId:1,date:'2026/10/02',activity:'社區共餐',feeling:'與鄰居一起用餐，願意再來。'},{caseId:5,date:'2026/10/03',activity:'手作課程',feeling:'在志工陪同下完成作品，覺得有成就感。'},{caseId:6,date:'2026/10/01',activity:'社區共餐',feeling:'喜歡和其他人聊天，下次時間待確認。'},{caseId:7,date:'2026/10/03',activity:'手作課程',feeling:'喜歡手作主題，願意嘗試下一次課程。'},{caseId:8,date:'2026/10/02',activity:'長者棋藝活動',feeling:'遇到熟悉的鄰居，希望持續參與。'},{caseId:9,date:'2026/10/01',activity:'社區歌唱活動',feeling:'喜歡熟悉的歌曲，回程交通待確認。'},{caseId:10,date:'2026/10/02',activity:'公園健走團',feeling:'喜歡與同伴交流，希望先確認下次路線。'}];
function openStat(kind){statKind=kind;fromStat=false;search='';caseFilter='全部';go('statDetail')}
function openStatCase(id){fromStat=true;openCase(id)}
function statPerson(id){return `<div class="namecell">${caseAvatar(id)}${esc(cases[id][0])}</div>`}
function statDetail(){const title=statTitles[statKind],count=[cases.length,followups.length,monthParticipations().length,pendingTasks.length][statKind],descriptions=['目前帳號具有服務／查看權限的個案。','預計於 2026/10/05–2026/10/11 聯繫或追蹤的長者。','2026 年 10 月已記錄的實際參與結果。','下一次接觸時，可以直接確認的工作事項。'];let content='';
if(statKind===0){content=`<div class="card tablecard"><table><thead><tr><th>姓名</th><th>年齡</th><th>最後接觸</th><th>待處理事項</th><th>操作</th></tr></thead><tbody>${cases.map((c,i)=>`<tr><td>${statPerson(i)}</td><td>${caseAge(c)} 歲</td><td>${c[2]||'尚未接觸'}</td><td>${esc(c[4])}</td><td>${btn('查看個案',`openStatCase(${i})`,'light')}</td></tr>`).join('')}</tbody></table></div>`}
else{const items=statKind===1?followups:statKind===2?monthParticipations():pendingTasks;content=`<div class="grid two">${items.map((item,i)=>`<article class="card stat-item"><div class="row between">${statPerson(item.caseId)}${badge(statKind===1?'待追蹤':statKind===2?'已參與':'待確認',statKind===2?'green':'orange')}</div><h2 class="space">${esc(item.activity||item.task)}</h2>${statKind===1?`<p class="small space">預計追蹤日期：${item.due}</p><p class="small">最後接觸：${cases[item.caseId][2]}</p>`:statKind===2?`<p class="small space">參與日期：${esc(item.date)}</p><p class="muted space">${esc(item.feeling)}</p>`:`<p class="muted space">${esc(item.note)}</p>`}<div class="space">${btn('查看個案',`openStatCase(${item.caseId})`,'light')}</div></article>`).join('')}</div>`}
return `<div class="crumb"><button onclick="go('home')">首頁</button><span>／</span><span>${title}</span></div>${header(title,descriptions[statKind],btn('返回首頁',"go('home')",'secondary'))}<div class="row between" style="margin-bottom:20px"><div class="lock">🔒 僅顯示目前帳號授權查看的示範資料</div>${badge('共 '+count+(statKind<2?' 位':' 筆'))}</div>${content}`}


let caseRecords={0:records},caseTracks={},caseGenders=cases.map(c=>c[0].includes('奶奶')?'女性':'男性');
function caseCode(){return 'A'+String(selectedCase+1).padStart(3,'0')}
function isTracked(resourceId){return (caseTracks[selectedCase]||[]).includes(resourceId)}
function createTracking(){const list=caseTracks[selectedCase]||(caseTracks[selectedCase]=[]);if(!list.includes(selectedResource))list.push(selectedResource);modal='';saveDemo();render();toast('已建立'+cname()+'的活動追蹤')}
function suggestedResources(){if(selectedCase===0)return [0];const text=records.map(r=>r.text||r.summary).join(' ');const keys=[['下棋','棋藝'],['共餐','一起吃飯'],['健走','散步'],['手作'],['唱歌','歌唱']];return keys.map((terms,i)=>terms.some(t=>text.includes(t))?i:-1).filter(i=>i>=0)}
function emptyTrends(){if(selectedCase===0)return participationJourney();return `<div class="card"><h2>${esc(cname())}的參與趨勢</h2>${records.some(r=>r.feedback)?`<ul>${records.filter(r=>r.feedback).map(r=>`<li>${esc(r.date)} · ${esc(r.source)} · ${esc(r.status)}<p class="small">${esc(r.feeling||r.summary)}</p></li>`).join('')}</ul>`:'<p class="muted space">尚無參與回饋。新增參與結果後，這裡會呈現紀錄中的變化。</p>'}<div class="callout gap">本區呈現服務紀錄中的生活與參與變化，不作醫療診斷。</div></div>`}
function otherFiles(){return `<div class="card"><h2>${esc(cname())}的檔案資料</h2><div class="restricted gap">🔒 受限資料 · 依角色與服務權限開放</div><p class="muted space">目前有 ${records.length} 筆接觸／參與紀錄。原始文字可從歷次接觸逐筆查看。</p><div class="space">${btn('查看歷次接觸',"tab('timeline')",'light')}</div></div>`}
const basicFields=[['name','姓名'],['gender','性別'],['birthday','生日'],['address','居住地'],['contact','聯絡方式'],['caregiver','主要照護者'],['family','家庭狀況'],['medical','就醫狀況']];
let caseBasics={0:{address:'臺中市南區',contact:'04-2XXX-XXXX',caregiver:'女兒（白天工作）',medical:'固定回診'}},basicSuggestions={},basicHistory={};
function saveDemo(){deletedRecords=deletedRecords.filter(item=>item.expiresAt>Date.now());syncParticipationIndex();try{demoLocalStorage.setItem('linkage-demo-v2',JSON.stringify({deletedRecords,cases,caseRecords,caseTracks,caseGenders,participations,pendingTasks,followups,caseBasics,basicSuggestions,basicHistory}))}catch(e){toast('瀏覽器儲存空間不足，請先匯出或減少照片；本次資料可能未儲存')}}
