function localToday(now=new Date()){return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function ageFromBirthday(birthday,now=new Date()){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(birthday||''))return null;
  const [year,month,day]=birthday.split('-').map(Number);
  const birth=new Date(year,month-1,day);
  if(birth.getFullYear()!==year||birth.getMonth()!==month-1||birth.getDate()!==day||birthday>localToday(now))return null;
  return now.getFullYear()-year-(now.getMonth()+1<month||(now.getMonth()+1===month&&now.getDate()<day)?1:0);
}
function caseAge(c){return c[5]?ageFromBirthday(c[5])??'—':c[1]}
